  `leftover_return_decision_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `leftover_return_request_id` BIGINT UNSIGNED NOT NULL,
  `decision` VARCHAR(12) NOT NULL,
  `decision_reason` VARCHAR(300) NOT NULL,
  `stock_movement_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`leftover_return_decision_id`),
  UNIQUE KEY `uq_leftover_return_decision_1` (`leftover_return_request_id`),
  UNIQUE KEY `uq_leftover_return_decision_2` (`stock_movement_id`),
  UNIQUE KEY `uq_leftover_return_decision_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_leftover_return_decision_leftover_return_request` FOREIGN KEY (`leftover_return_request_id`) REFERENCES `leftover_return_request` (`leftover_return_request_id`),
  CONSTRAINT `fk_leftover_return_decision_stock_movement` FOREIGN KEY (`stock_movement_id`) REFERENCES `stock_movement` (`stock_movement_id`),
  CONSTRAINT `fk_leftover_return_decision_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_leftover_return_decision_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_leftover_return_decision_1` CHECK (`decision` IN ('accepted','refused')),
  CONSTRAINT `ck_leftover_return_decision_2` CHECK (`is_backfilled` IN (0,1)),
  CONSTRAINT `ck_leftover_return_decision_3` CHECK ((decision = 'accepted') = (stock_movement_id IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Pharmacist decides (second actor).';

CREATE TABLE `order_item_supply` (
  `order_item_supply_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `clinical_order_item_id` BIGINT UNSIGNED NOT NULL,
  `dispensing_id` BIGINT UNSIGNED NOT NULL,
  `quantity_allocated` DECIMAL(10,2) NOT NULL,
  `reverses_order_item_supply_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`order_item_supply_id`),
  UNIQUE KEY `uq_order_item_supply_1` (`order_item_supply_id`, `clinical_order_item_id`),
  UNIQUE KEY `uq_order_item_supply_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_order_item_supply_dispensing` FOREIGN KEY (`dispensing_id`) REFERENCES `dispensing` (`dispensing_id`),
  CONSTRAINT `fk_order_item_supply_order_item_supply` FOREIGN KEY (`reverses_order_item_supply_id`) REFERENCES `order_item_supply` (`order_item_supply_id`),
  CONSTRAINT `fk_order_item_supply_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_order_item_supply_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_order_item_supply_1` CHECK (`is_backfilled` IN (0,1)),
  CONSTRAINT `ck_order_item_supply_2` CHECK (quantity_allocated > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Order item x Dispensing: marks a dispensing as order-linked (R6.2 scope).';

CREATE TABLE `counter_sale_return` (
  `counter_sale_return_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `counter_sale_id` BIGINT UNSIGNED NOT NULL,
  `returned_stock_movement_id` BIGINT UNSIGNED NOT NULL,
  `reason` VARCHAR(300) NOT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`counter_sale_return_id`),
  UNIQUE KEY `uq_counter_sale_return_1` (`returned_stock_movement_id`),
  UNIQUE KEY `uq_counter_sale_return_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_counter_sale_return_counter_sale` FOREIGN KEY (`counter_sale_id`) REFERENCES `counter_sale` (`counter_sale_id`),
  CONSTRAINT `fk_counter_sale_return_stock_movement` FOREIGN KEY (`returned_stock_movement_id`) REFERENCES `stock_movement` (`stock_movement_id`),
  CONSTRAINT `fk_counter_sale_return_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_counter_sale_return_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_counter_sale_return_1` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Stock side of a counter-sale return.';

CREATE TABLE `custody_handoff` (
  `custody_handoff_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `dispensing_id` BIGINT UNSIGNED NOT NULL,
  `giver_staff_id` BIGINT UNSIGNED NOT NULL,
  `recipient_staff_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `recipient_attendant_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `quantity` DECIMAL(10,2) NOT NULL,
  `handoff_purpose` VARCHAR(22) NOT NULL,
  `leftover_return_decision_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`custody_handoff_id`),
  UNIQUE KEY `uq_custody_handoff_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_custody_handoff_dispensing` FOREIGN KEY (`dispensing_id`) REFERENCES `dispensing` (`dispensing_id`),
  CONSTRAINT `fk_custody_handoff_staff` FOREIGN KEY (`giver_staff_id`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_custody_handoff_recipient_staff_id` FOREIGN KEY (`recipient_staff_id`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_custody_handoff_patient_attendant` FOREIGN KEY (`recipient_attendant_id`) REFERENCES `patient_attendant` (`patient_attendant_id`),
  CONSTRAINT `fk_custody_handoff_leftover_return_decision` FOREIGN KEY (`leftover_return_decision_id`) REFERENCES `leftover_return_decision` (`leftover_return_decision_id`),
  CONSTRAINT `fk_custody_handoff_recorded_by` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_custody_handoff_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_custody_handoff_1` CHECK (`handoff_purpose` IN ('supply_to_nurse','take_home','leftover_to_family')),
  CONSTRAINT `ck_custody_handoff_2` CHECK (`is_backfilled` IN (0,1)),
  CONSTRAINT `ck_custody_handoff_3` CHECK (quantity > 0),
  CONSTRAINT `ck_custody_handoff_4` CHECK (giver_staff_id = recorded_by),
  CONSTRAINT `ck_custody_handoff_5` CHECK ((recipient_staff_id IS NULL) <> (recipient_attendant_id IS NULL)),
  CONSTRAINT `ck_custody_handoff_6` CHECK ((handoff_purpose = 'leftover_to_family') = (leftover_return_decision_id IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Ternary: dispensing x giver x recipient (staff or attendant). Giver records (G1).';

CREATE TABLE `counter_sale_refund` (
  `counter_sale_refund_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `counter_sale_id` BIGINT UNSIGNED NOT NULL,
  `counter_sale_return_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `amount` DECIMAL(12,2) NOT NULL,
  `method` VARCHAR(8) NOT NULL,
  `receipt_number` VARCHAR(30) NOT NULL,
  `approval_request_id` BIGINT UNSIGNED NOT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  `corrects_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  PRIMARY KEY (`counter_sale_refund_id`),
  UNIQUE KEY `uq_counter_sale_refund_1` (`receipt_number`),
  UNIQUE KEY `uq_counter_sale_refund_2` (`approval_request_id`),
  UNIQUE KEY `uq_counter_sale_refund_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_counter_sale_refund_counter_sale` FOREIGN KEY (`counter_sale_id`) REFERENCES `counter_sale` (`counter_sale_id`),
  CONSTRAINT `fk_counter_sale_refund_counter_sale_return` FOREIGN KEY (`counter_sale_return_id`) REFERENCES `counter_sale_return` (`counter_sale_return_id`),
  CONSTRAINT `fk_counter_sale_refund_approval_request` FOREIGN KEY (`approval_request_id`) REFERENCES `approval_request` (`approval_request_id`),
  CONSTRAINT `fk_counter_sale_refund_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_counter_sale_refund_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `fk_counter_sale_refund_counter_sale_refund` FOREIGN KEY (`corrects_id`) REFERENCES `counter_sale_refund` (`counter_sale_refund_id`),
  CONSTRAINT `ck_counter_sale_refund_1` CHECK (`method` IN ('cash','upi','card')),
  CONSTRAINT `ck_counter_sale_refund_2` CHECK (`is_backfilled` IN (0,1)),
  CONSTRAINT `ck_counter_sale_refund_3` CHECK (amount > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Money side of a counter-sale return; owner approval mandatory (CR-3).';

CREATE TABLE `custody_handoff_acknowledgement` (
  `custody_handoff_acknowledgement_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `custody_handoff_id` BIGINT UNSIGNED NOT NULL,
  `acknowledged_quantity` DECIMAL(10,2) NOT NULL,
  `ack_method` VARCHAR(23) NOT NULL,
  `witness_note` VARCHAR(300) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`custody_handoff_acknowledgement_id`),
  UNIQUE KEY `uq_custody_handoff_acknowledgement_1` (`custody_handoff_id`),
  UNIQUE KEY `uq_custody_handoff_acknowledgement_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_custody_handoff_acknowledgement_custody_handoff` FOREIGN KEY (`custody_handoff_id`) REFERENCES `custody_handoff` (`custody_handoff_id`),
  CONSTRAINT `fk_custody_handoff_acknowledgement_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_custody_handoff_acknowledgement_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_custody_handoff_acknowledgement_1` CHECK (`ack_method` IN ('self_logged_staff','witnessed_attendant')),
  CONSTRAINT `ck_custody_handoff_acknowledgement_2` CHECK (`is_backfilled` IN (0,1)),
  CONSTRAINT `ck_custody_handoff_acknowledgement_3` CHECK (acknowledged_quantity >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Recipient side (G1). Witness must differ from giver (CR-4).';
